  function getRoadmapEntry(trackId, phaseNum) {
    var key = trackId + '-p' + phaseNum;
    return ROADMAP[key] || null;
  }
  function getLesson(lessonId) {
    return LESSONS[lessonId] || null;
  }
  function getTrackRoadmap(trackId) {
    var out = [];
    for (var k in ROADMAP) {
      if (k.indexOf(trackId + '-p') === 0) {
        out.push(ROADMAP[k]);
      }
    }
    out.sort(function(a, b){ return a.phase - b.phase; });
    return out;
  }
  function getTrack(trackId) {
    for (var i = 0; i < TRACKS.length; i++) {
      if (TRACKS[i].id === trackId) return TRACKS[i];
    }
    return null;
  }

